contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // run takes an arbitrary amount of wei that will be forwarded to c.go
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance to fund call");
        // record observable pre-state
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceCBefore = address(c).balance;
        // perform the call and capture whether it reverted
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        // observe post-state
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceCAfter = address(c).balance;
        // General rule: if the call did NOT revert, owner must be unchanged and contract balance must be zero
        assert(reverted || (ownerBefore == ownerAfter && balanceCAfter == 0));
    }
    receive() external payable {}
}

